const WIDTHS = [480, 720, 800, 1024, 1600] as const

type PictureProps = {
  name: string
  alt: string
  sizes: string
  width: number
  height: number
  priority?: boolean
  className?: string
  /** Extra widths on top of the standard set, for images that also have a larger file (see scripts/optimise-images.mjs). */
  extraWidths?: readonly number[]
  /** Largest file that exists, for small originals that are not enlarged past it. */
  maxWidth?: number
}

/** Responsive AVIF with WebP fallback, generated by scripts/optimise-images.mjs. */
export function Picture({ name, alt, sizes, width, height, priority = false, className = '', extraWidths = [], maxWidth = Infinity }: PictureProps) {
  const srcset = (ext: string) =>
    [...WIDTHS, ...extraWidths]
      .filter((w) => w <= maxWidth)
      .map((w) => `/images/${name}-${w}.${ext} ${w}w`).join(', ')
  return (
    <picture>
      <source type="image/avif" srcSet={srcset('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcset('webp')} sizes={sizes} />
      <img
        src={`/images/${name}-1024.webp`}
        alt={alt}
        width={width}
        height={height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : 'auto'}
        className={className}
      />
    </picture>
  )
}
